import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.C4u0TEY0.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),r={name:"guide/introduction.md"};function n(s,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>apk.js runs Android APKs in the browser with plain JavaScript. It reads an APK, executes the application bytecode, and draws the resulting UI on a Canvas. There is no device, emulator or native library involved.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>An APK is a zip archive. apk.js pulls five things out of it:</p><ol><li><code>classes.dex</code> — application bytecode, executed by the DEX interpreter.</li><li><code>AndroidManifest.xml</code> — binary AXML, describing the package, activities and theme.</li><li><code>resources.arsc</code> — the resource table, resolving IDs to strings, colors and file paths.</li><li><code>res/</code> files — layouts and drawables, also binary AXML.</li><li><code>assets/</code> files — application assets, served through the runtime.</li></ol><p>The interpreter calls into a Canvas-backed implementation of the Android Framework. When the app calls <code>setContentView</code>, inflates a layout or measures a view, that call lands in the framework subset, which knows how to paint to a canvas.</p><h2 id="what-it-supports" tabindex="-1">What it supports <a class="header-anchor" href="#what-it-supports" aria-label="Permalink to &quot;What it supports&quot;">​</a></h2><p>The project targets small and medium Java/Kotlin apps. The sample <code>hello-dex.apk</code> exercises counters, text input, dynamic views, progress bars, shape drawables, <code>Build</code> info, reflection and multi-activity navigation.</p><p>Real apps work too. <code>image-debug/devinfo.png</code> is a render of a hardware-info app running through the interpreter.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/apk.js/guide/quick-start.html">Quick start</a> — get the demo running.</li><li><a href="/apk.js/guide/embedding.html">Embedding</a> — put a simulator on your own page.</li><li><a href="/apk.js/internals/architecture.html">Architecture</a> — how the pieces fit together.</li></ul>',11)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
